package com.ktb.hackathon.team11.schedule;import com.ktb.hackathon.team11.global.response.ApiResponse;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import lombok.RequiredArgsConstructor;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;import java.time.*;import java.util.*;
@RestController @RequestMapping("/api/v1") @RequiredArgsConstructor public class ScheduleController{private final ScheduleService service;@PostMapping("/task-templates/{id}/schedules")@ResponseStatus(HttpStatus.CREATED)ApiResponse<Long> create(@PathVariable long id,@Valid @RequestBody ScheduleRequest r){return ApiResponse.of("SCHEDULE_CREATED",service.create(id,r.managerId(),r.assigneeId(),r.startDate(),r.endDate(),r.startTime(),r.endTime(),r.recurrenceType(),r.daysOfWeek(),r.earlyAllowanceMinutes(),r.lateAllowanceMinutes()).getId());}@PostMapping("/groups/{groupId}/assignments/generate")ApiResponse<Integer> generate(@PathVariable long groupId,@Valid @RequestBody GenerateRequest r){return ApiResponse.of("ASSIGNMENTS_GENERATED",service.generate(groupId,r.managerId(),r.targetDate()));}public record ScheduleRequest(@NotNull Long managerId,Long assigneeId,@NotNull LocalDate startDate,LocalDate endDate,@NotNull LocalTime startTime,@NotNull LocalTime endTime,@NotNull RecurrenceType recurrenceType,Set<DayOfWeek> daysOfWeek,@PositiveOrZero int earlyAllowanceMinutes,@PositiveOrZero int lateAllowanceMinutes){}public record GenerateRequest(@NotNull Long managerId,@NotNull LocalDate targetDate){}}
